_B85 = np.zeros(128, np.uint64)
_B85[np.frombuffer(b"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz!#$%&()*+-;<=>?@^_`{|}~", np.uint8)] = np.arange(85, dtype=np.uint64)


def _raw(packed):
    """The bytes a (base85 of whole 4-byte groups, length) pair holds, decoded by numpy."""
    text, n = packed
    d = _B85[np.frombuffer(text.encode(), np.uint8)].reshape(-1, 5)
    v = (((d[:, 0] * 85 + d[:, 1]) * 85 + d[:, 2]) * 85 + d[:, 3]) * 85 + d[:, 4]
    return v.astype(">u4").tobytes()[:n]
