class Decoder:
    def __init__(self,point):
        self.L=point.L
        self.m=(point.L*point.L-1)//2
        self.key=(point.L,point.p,point.xi)
        self.table=None
        if self.key in TABLES:
            raw=_raw(TABLES[self.key])
            if point.L<7:
                self.table=np.unpackbits(np.frombuffer(raw,np.uint8))
            else:
                self.table=np.zeros(1<<self.m,dtype=np.uint8)
                self.table[np.cumsum(np.frombuffer(raw,'<u4'))]=1
        if self.L==7 or self.table is None:
            h=((np.asarray(CODES[point.L],dtype=np.uint32)[:,None]>>np.arange(self.m))&1).astype(np.uint8).T
            self.match=pymatching.Matching(h, faults_matrix=np.asarray(OBS[point.L],dtype=np.uint8)[None,:])
    def decode(self,s):
        v=np.packbits(s[:,:self.m],axis=1,bitorder='little')
        code=v[:,0].astype(np.uint32)
        for i in range(1,v.shape[1]): code|=v[:,i].astype(np.uint32)<<(8*i)
        if self.L<7 and self.table is not None: return self.table[code]
        u,inv=np.unique(code,return_inverse=True)
        rev=np.zeros_like(u)
        for b in range(self.m): rev|=((u>>b)&1)<<(self.m-1-b)
        canonical=np.minimum(u,rev)
        syn=((canonical[:,None]>>np.arange(self.m))&1).astype(np.uint8)
        pred=self.match.decode_batch(syn)[:,0]
        if self.table is not None: pred^=self.table[canonical]
        pred^=((rev<u)&((np.bitwise_count(u)&1)!=0)).astype(np.uint8)
        return pred[inv]
def build_decoder(point):
    return Decoder(point)

