def unpack7(point):
 n,*data=_PACKED7
 a=np.frombuffer(_raw(data),np.uint8)
 b=a[:-n]
 starts=np.r_[0,np.flatnonzero((b[:-1]&128)==0)+1]
 pos=np.arange(len(b))-np.repeat(starts,np.diff(np.r_[starts,len(b)]))
 gap=np.add.reduceat((b&127).astype(np.uint32)<<(7*pos.astype(np.uint32)),starts)
 keys=np.cumsum(gap,dtype=np.uint32)
 bit=(point.p>.007)*3+{2:0,5:1,10:2}[point.xi]
 table=np.zeros(1<<24,np.uint8)
 table[keys]=(a[-n:]>>bit)&1
 return table


