class SymmetricDecoder:
 def __init__(self,point):
  raw=_raw(SYM_PAYLOAD);raw=np.frombuffer(raw,np.uint8).reshape(2,-1).T.copy().tobytes();arr=np.frombuffer(raw,np.float16).astype(np.float32);pos=0
  H=np.ones((1,1),np.float32)
  for shape in SYM_SHAPES:
   n=shape[0]*shape[1]*shape[2];c=arr[pos:pos+n].reshape(shape);pos+=n;H=(H@c.reshape(shape[0],-1)).reshape(-1,shape[2])
  C=arr[pos:].reshape(4,SYM_C,SYM_C)[int(point.p==.01)+2*int(point.xi==10)]
  self.H=H;self.HC=H@C
  self.head=int(point.p==.01)+2*int(point.xi==10)
  raw=_raw(BDD_PAYLOAD);n,self.root=np.frombuffer(raw,np.uint32,count=2);self.BN=np.frombuffer(raw,np.uint16,count=2*n,offset=8).reshape(-1,2);self.BB=np.frombuffer(raw,np.uint8,count=n,offset=8+4*n)
  ar=np.arange(4096,dtype=np.uint32);self.rev=np.zeros(4096,np.uint32)
  for b in range(12):self.rev|=((ar>>b)&1)<<(11-b)
  self.sign=1-2*(np.bitwise_count(ar)&1).astype(np.int8)
 def decode(self,s):
  v=np.packbits(s[:,:24],axis=1,bitorder='little');k=v[:,0].astype(np.uint32)|(v[:,1].astype(np.uint32)<<8)|(v[:,2].astype(np.uint32)<<16)
  u,iv=np.unique(k,return_inverse=True);a=u>>12;b=self.rev[u&4095];pp=(self.HC[a]*self.H[b]).sum(1)*self.sign[a];y=(pp>0).astype(np.uint8);y[u==0]=0
  cur=np.full(len(u),self.root,np.uint16)
  for _ in range(24):
   sel=cur>=16
   if not sel.any():break
   j=cur[sel]-16;cur[sel]=self.BN[j,(u[sel]>>self.BB[j])&1]
  y^=((cur>>self.head)&1).astype(np.uint8)
  return y[iv]
def build_decoder(point):
 if point.L==7 and point.xi in (5,10):return SymmetricDecoder(point)
 dec=Decoder(point)
 if point.L==7 and point.xi==2:dec.table=unpack7(point)
 return dec
